class Solution {
public:
    int maxVacationDays(vector<vector<int>>& flights, vector<vector<int>>& days) {
        int n = flights.size();
        int k = days[0].size();
        vector<int> dp(n, -1);
        dp[0] = 0;

        for (int w = 0; w < k; w++) {
            vector<int> next_dp(n, -1);
            for (int curr = 0; curr < n; curr++) {
                if (dp[curr] == -1) continue;
                for (int dest = 0; dest < n; dest++) {
                    if (dest == curr || flights[curr][dest] == 1) {
                        next_dp[dest] = max(next_dp[dest], dp[curr] + days[dest][w]);
                    }
                }
            }
            dp = move(next_dp);
        }

        int ans = 0;
        for (int val : dp) ans = max(ans, val);
        return ans;
    }
};

class Solution {
    public int maxVacationDays(int[][] flights, int[][] days) {
        int n = flights.length;
        int k = days[0].length;
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int w = 0; w < k; w++) {
            int[] nextDp = new int[n];
            java.util.Arrays.fill(nextDp, -1);
            for (int curr = 0; curr < n; curr++) {
                if (dp[curr] == -1) continue;
                for (int dest = 0; dest < n; dest++) {
                    if (dest == curr || flights[curr][dest] == 1) {
                        nextDp[dest] = Math.max(nextDp[dest], dp[curr] + days[dest][w]);
                    }
                }
            }
            dp = nextDp;
        }

        int ans = 0;
        for (int val : dp) ans = Math.max(ans, val);
        return ans;
    }
}

