var maxVacationDays = function(flights, days) {
    const n = flights.length;
    const k = days[0].length;
    let dp = new Array(n).fill(-1);
    dp[0] = 0;

    for (let w = 0; w < k; w++) {
        const nextDp = new Array(n).fill(-1);
        for (let curr = 0; curr < n; curr++) {
            if (dp[curr] === -1) continue;
            for (let dest = 0; dest < n; dest++) {
                if (dest === curr || flights[curr][dest] === 1) {
                    nextDp[dest] = Math.max(nextDp[dest], dp[curr] + days[dest][w]);
                }
            }
        }
        dp = nextDp;
    }

    return Math.max(...dp);
};
